-- Umbra Gore & Effects, kid mode for particles: particles\alpha_add on the DX8 (R1) renderer.
-- Exactly the C++ particle blender (xray-monolith Blender_Particle.cpp, R1 branch) with this
-- mod list's shaders.xr settings for particles\alpha_add (from base:files.db0): priority 3, strict sorting off,
-- blending ALPHA-ADD, texture clamp on. It only exists so that effects pointed at zgo\particle_*
-- load on this renderer (a missing shader name is fatal there); kid mode hides nothing here.
-- Generated by tools/zgo_kidfx/kidfx_pe.py shaders --write; tests/zgo_test_kidfx.lua checks it.

function normal(shader, t_base, t_second, t_detail)
	shader:begin("particle", "particle")
		:sorting(3, false)
		:fog(false)
		:zb(true, false)
		:blend(true, blend.srcalpha, blend.one)
		:aref(true, 0)
	shader:sampler("s_base"):texture(t_base):clamp()
end

